package com.bank.export;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ExportArchiveDemo {
    private static final Logger log = Logger.getLogger(ExportArchiveDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // Priya's name includes a non-ASCII accented character to prove encoding.
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priyá Sharmá", new BigDecimal("250000.00"));

        CustomerExportService export = new CustomerExportService();

        // TEXT PATH: write with explicit UTF-8, read back with explicit UTF-8.
        byte[] fileBytes = export.writeNames(List.of(rajesh, priya));
        List<String> namesOk = export.readNames(fileBytes, StandardCharsets.UTF_8);
        log.info(() -> "Read back (UTF-8, correct): " + namesOk);

        // WRONG CHARSET: decode UTF-8 bytes as ISO-8859-1 → silent corruption.
        List<String> namesBad = export.readNames(fileBytes, StandardCharsets.ISO_8859_1);
        log.warning(() -> "Read back (ISO-8859-1, corrupted): " + namesBad);

        // BINARY PATH: copy a cheque image blob with byte streams, exact bytes.
        ImageArchiveService archive = new ImageArchiveService();
        byte[] cheque = new byte[] {(byte)0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A}; // PNG header
        byte[] copied = archive.copyCheque(new ByteArrayInputStream(cheque));
        boolean identical = java.util.Arrays.equals(cheque, copied);
        log.info(() -> "Cheque byte-for-byte identical = " + identical);
    }
}

