class CustomerExportService {
    private static final Logger log = Logger.getLogger(CustomerExportService.class.getName());

    // CHARACTER stream bridge for TEXT: explicit UTF-8 encoding.
    byte[] writeNames(java.util.List<Account> accounts) throws java.io.IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (var w = new java.io.BufferedWriter(
                new java.io.OutputStreamWriter(bytes, StandardCharsets.UTF_8))) {
            for (Account a : accounts) {
                w.write(a.getAccountId() + "," + a.getHolderName());
                w.newLine();
            }
        }
        log.fine(() -> "Wrote " + accounts.size() + " names as UTF-8");
        return bytes.toByteArray();
    }

    // Decode with a SPECIFIED charset so the result is deterministic.
    java.util.List<String> readNames(byte[] data, java.nio.charset.Charset cs)
            throws java.io.IOException {
        java.util.List<String> out = new java.util.ArrayList<>();
        try (var r = new java.io.BufferedReader(
                new java.io.InputStreamReader(new ByteArrayInputStream(data), cs))) {
            String line;
            while ((line = r.readLine()) != null) {
                out.add(line.split(",", 2)[1]);
            }
        }
        return out;
    }
}

