class ImageArchiveService {
    private static final Logger log = Logger.getLogger(ImageArchiveService.class.getName());

    // BYTE streams for BINARY: no decoding, exact bytes preserved.
    byte[] copyCheque(java.io.InputStream in) throws java.io.IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        try (var bin = new java.io.BufferedInputStream(in);
             var bout = new java.io.BufferedOutputStream(out)) {
            bin.transferTo(bout);   // raw byte copy
        }
        log.fine("Copied cheque image via byte streams");
        return out.toByteArray();
    }
}

